#include "conv2d_kernel.h"
extern "C" __global__ __aicore__ void conv2d_custom_fp16(GM_ADDR x,GM_ADDR w,GM_ADDR b,GM_ADDR y,GM_ADDR t){
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    Conv2dKernel<half> k; k.Init(x,w,b,y,t,&p); k.Process();
}
extern "C" void conv2d_do_fp16(uint32_t d,void* s,uint8_t* x,uint8_t* w,uint8_t* b,uint8_t* y,uint8_t* t){
    conv2d_custom_fp16<<<d,nullptr,s>>>(x,w,b,y,t);
}

