#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "conv2d_tiling.h"
extern "C" void conv2d_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace conv2d_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_conv2d_v2(const at::Tensor &x, const at::Tensor &w, const at::Tensor &bias, int64_t stride, int64_t pad) {
    TORCH_CHECK(stride==1&&pad==1,"only s=1,p=1 supported"); TORCH_CHECK(x.dim()==4&&w.dim()==4,"[N,C,H,W]");
    TORCH_CHECK(x.scalar_type()==at::kHalf,"fp16 only"); TORCH_CHECK(x.is_contiguous(),"contiguous");
    const auto N=x.sizes()[0], Ci=x.sizes()[1], H=x.sizes()[2], W=x.sizes()[3];
    const auto Co=w.sizes()[0], Kh=w.sizes()[2], Kw=w.sizes()[3];
    const auto M=static_cast<int32_t>(N*Co*H);
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({N,Co,H,W},x.options());
    at::Tensor tc=at::empty({sizeof(Conv2dKernelTiling)},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<Conv2dKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=static_cast<int32_t>(W); t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    t->Ci=static_cast<int32_t>(Ci); t->Co=static_cast<int32_t>(Co); t->H=static_cast<int32_t>(H); t->W=static_cast<int32_t>(W);
    t->Kh=static_cast<int32_t>(Kh); t->Kw=static_cast<int32_t>(Kw);
    t->inTotal=static_cast<int32_t>(N*Ci*H*W); t->outTotal=static_cast<int32_t>(N*Co*H*W);
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    conv2d_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(w.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(bias.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_conv2d_v2_ext, m) { m.def("run_conv2d_v2",&conv2d_ext::run_conv2d_v2,""); }

