#pragma once
#ifndef CONV2D_KERNEL_H
#define CONV2D_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "conv2d_tiling.h"

template <typename T>
class Conv2dKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR b, GM_ADDR y, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), t_.inTotal);
        wGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(w), t_.Co * t_.Ci * t_.Kh * t_.Kw);
        bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(b), t_.Co);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), t_.outTotal);
        if ASCEND_IS_AIV { pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum(); }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < t_.tasksPerCore; ++li) {
                const int bx = ci * t_.tasksPerCore + li; if (bx >= BlockCount()) continue;
                for (int r = 0; r < sr_; ++r) {
                    const int ri = bx * t_.blockM + si * sr_ + r; if (ri < t_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t ri) {
        // ri = n * Co * H + co * H + h
        int32_t n = ri / (t_.Co * t_.H);
        int32_t co = (ri / t_.H) % t_.Co;
        int32_t h = ri % t_.H;
        int32_t inBase = n * t_.Ci * t_.H * t_.W;
        int32_t outBase = (n * t_.Co + co) * t_.H * t_.W + h * t_.W;

        for (int32_t ow = 0; ow < t_.W; ++ow) {
            float sum = static_cast<float>(bGM_.GetValue(co));
            for (int32_t ci = 0; ci < t_.Ci; ++ci) {
                for (int32_t kh = 0; kh < t_.Kh; ++kh) {
                    int32_t ih = h + kh - 1; // padding=1 offset
                    if (ih < 0 || ih >= t_.H) continue;
                    for (int32_t kw = 0; kw < t_.Kw; ++kw) {
                        int32_t iw = ow + kw - 1;
                        if (iw < 0 || iw >= t_.W) continue;
                        int32_t xi = inBase + ci * t_.H * t_.W + ih * t_.W + iw;
                        int32_t wi = (co * t_.Ci + ci) * t_.Kh * t_.Kw + kh * t_.Kw + kw;
                        sum += static_cast<float>(xGM_.GetValue(xi)) *
                               static_cast<float>(wGM_.GetValue(wi));
                    }
                }
            }
            yGM_.SetValue(outBase + ow, static_cast<T>(sum));
        }
    }
private:
    Conv2dKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> xGM_, wGM_, bGM_, yGM_;
};
#endif
